// Copied from shared/ by scripts/sync.mjs; edit shared/ and run the script.
/**
 * Deleting files by argv on every platform, with no shell to read the paths.
 *
 * Claude Code starts a plugin's command without a shell. On a POSIX system
 * `rm -f -- <paths>` takes each path as one argument. Windows has no `rm`,
 * and `cmd.exe /c del` would read the paths again by cmd's own rules (`%VAR%`
 * expanded, quotes stripped), so there PowerShell runs `Remove-Item
 * -LiteralPath` from an encoded script: the paths travel inside the script as
 * single-quoted literals and are never parsed as a command line.
 */

/** The script as PowerShell's `-EncodedCommand` takes it: UTF-16LE, then base64. */
export function encodePowerShell(script: string): string {
  let bytes = ''
  for (let index = 0; index < script.length; index += 1) {
    const unit = script.charCodeAt(index)
    bytes += String.fromCharCode(unit & 0xff, unit >> 8)
  }

  return btoa(bytes)
}

/**
 * A path as a PowerShell single-quoted literal: nothing in it is special but
 * a single quote, which PowerShell also reads in its curly forms (‘ ’ ‚ ‛);
 * each is doubled.
 */
export function powerShellLiteral(path: string): string {
  return `'${path.replace(/['\u2018\u2019\u201a\u201b]/g, quote => quote + quote)}'`
}

/** argv deleting `paths`, absent or not; relative paths resolve against the command's working directory. */
export function removeArgv(paths: readonly string[], isWindows: boolean): string[] {
  if (!isWindows) return ['rm', '-f', '--', ...paths]
  // Only files are deleted, and an absent path is passed over: Remove-Item on a directory with
  // children asks whether to go on, a question no plugin answers. A file that cannot be deleted
  // stops the script, which exits 1.
  const script = `foreach ($p in @(${paths.map(powerShellLiteral).join(',')})) { if (Test-Path -LiteralPath $p -PathType Leaf) { Remove-Item -LiteralPath $p -Force -ErrorAction Stop } }`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

/**
 * argv deleting `paths` with everything under them, absent or not: a session's
 * transcript and its folder of subagent transcripts and tool output. The
 * caller checks every path lies where it means to delete; nothing here does.
 */
export function removeTreeArgv(paths: readonly string[], isWindows: boolean): string[] {
  if (!isWindows) return ['rm', '-rf', '--', ...paths]
  // -Recurse with -Force asks nothing: a folder with children is deleted whole.
  const script = `foreach ($p in @(${paths.map(powerShellLiteral).join(',')})) { if (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction Stop } }`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

files.hooks/collector.ts:
import { transcriptPath } from './shared/claude'
import { inProgressTask, parsePr, todoFilesOf, ultracodeAfter, ULTRA_MARKER } from './status'

/** Runs a command by argv; the hooks module passes one over `$.process.run`. */
export type Run = (
  argv: readonly string[],
  init?: { cwd?: string; timeoutMs?: number },
) => Promise<{ exitCode: number; stdout: string; stderr: string }>

/** What the collector reads through: the hooks module builds each over `$`. */
export type CollectorIo = {
  run: Run
  /** A file's text, or null when it is missing. */
  read: (path: string) => Promise<string | null>
  /** A directory's entries, or none when it is missing. */
  list: (path: string) => Promise<readonly { name: string; mtimeMs: number }[]>
  /** A file's size in bytes, or null when it is missing. */
  size: (path: string) => Promise<number | null>
}

/** How long a PR reading stands before `gh` is asked again, on the same branch. */
const PR_TTL_MS = 3 * 60 * 1000
/** The longest transcript line read for an ultracode switch; attachment records are small. */
const MAX_ATTACHMENT_LINE = 64 * 1024

/**
 * Reads the parts of the status the engine does not hand a plugin, each as cheaply
 * as it allows: the branch from git, the PR from `gh` at most every three
 * minutes, the task from the session's todo list, and ultracode from the
 * transcript, scanning only what was appended since the last read.
 */
export class StatusCollector {
  private ultra = { path: '', offset: 0, active: false }
  /** Set once the shell the transcript scan runs in could not be started (Windows has none): never tried again. */
  private hasNoShell = false
  private pr: { branch: string; at: number; value: { number: number; reviewState: string | null } | null } = {
    branch: '',
    at: 0,
    value: null,
  }

  /** The session's transcript once found, and when a search last came up empty. */
  private found = { session: '', path: '', missedAt: -Infinity }

  constructor(private readonly io: CollectorIo) {}

  /**
   * Runs a command that may be missing on this machine (git, gh, a shell):
   * one that cannot be started answers like one that failed, so a missing
   * tool empties its part of the status and never the whole read.
   */
  private async tryRun(argv: readonly string[], init?: { cwd?: string; timeoutMs?: number }) {
    try {
      return await this.io.run(argv, init)
    } catch (error) {
      if (!(error instanceof Error)) throw error
      return { exitCode: -1, stdout: '', stderr: error.message }
    }
  }

  /** The checked-out branch of `cwd`, or `''` outside a repository, on a detached head, or without git. */
  async branch(cwd: string): Promise<string> {
    const { exitCode, stdout } = await this.tryRun(['git', '-C', cwd, 'branch', '--show-current'], { timeoutMs: 2000 })

    return exitCode === 0 ? stdout.trim() : ''
  }

  /** The open PR of `branch`, asked of `gh` when the branch changed or the last answer is three minutes old. */
  async pullRequest(cwd: string, branch: string, now: number): Promise<{ number: number; reviewState: string | null } | null> {
    if (branch === '') return null
    if (this.pr.branch === branch && now - this.pr.at < PR_TTL_MS) return this.pr.value
    // Set first, so a slow or failing gh is asked once per window, not on every read.
    this.pr = { branch, at: now, value: this.pr.branch === branch ? this.pr.value : null }
    const { exitCode, stdout } = await this.tryRun(['gh', 'pr', 'view', '--json', 'number,reviewDecision'], { cwd, timeoutMs: 10_000 })
    this.pr.value = exitCode === 0 ? parsePr(stdout) : null

    return this.pr.value
  }

  /** The in-progress task of the session's newest todo list (under Claude Code's config directory), or `''`. */
  async task(configDirectory: string, session: string): Promise<string> {
    const directory = `${configDirectory}/todos`
    const [newest] = todoFilesOf(await this.io.list(directory), session)
    if (!newest) return ''
    const text = await this.io.read(`${directory}/${newest}`)

    return text === null ? '' : inProgressTask(text)
  }

  /**
   * The session's transcript, or null before it is written. It is looked for
   * in the folder named after `root` first. Where it is not there (the root
   * Claude Code named it after differs, such as a path it resolved through a
   * link), every project folder is searched for `<session>.jsonl`, at most
   * once a minute until it is found, and the place found is kept.
   */
  async transcript(configDirectory: string, root: string, session: string, now: number): Promise<string | null> {
    if (this.found.session !== session) this.found = { session, path: '', missedAt: -Infinity }
    if (this.found.path !== '' && (await this.io.size(this.found.path)) !== null) return this.found.path
    const named = transcriptPath(configDirectory, root, session)
    if ((await this.io.size(named)) !== null) {
      this.found.path = named

      return named
    }
    if (now - this.found.missedAt < TRANSCRIPT_RETRY_MS) return null
    const projects = `${configDirectory}/projects`
    for (const folder of await this.io.list(projects)) {
      const path = `${projects}/${folder.name}/${session}.jsonl`
      if ((await this.io.size(path)) !== null) {
        this.found.path = path

        return path
      }
    }
    this.found.missedAt = now

    return null
  }

  /**
   * Whether ultracode is on, from the transcript's switches. Transcripts grow
   * to hundreds of MB, so only the bytes appended since the last call are
   * scanned, by `tail` and `grep` outside the plugin's environment; a
   * transcript that shrank or changed path is scanned afresh.
   */
  async ultracode(transcript: string | null): Promise<boolean> {
    if (this.hasNoShell || transcript === null) return false
    const size = await this.io.size(transcript)
    if (size === null) return false
    if (this.ultra.path !== transcript || size < this.ultra.offset) this.ultra = { path: transcript, offset: 0, active: false }
    if (size === this.ultra.offset) return this.ultra.active
    // Read up to `size`. A record is appended in one write, so a cut line there is rare,
    // and only an ultracode switch inside such a line would go unseen.
    const script = `head -c "$2" "$1" | tail -c +"$3" | grep -a -F -e "$4" | awk -v max="$5" 'length($0) <= max'`
    const { exitCode, stdout, stderr } = await this.tryRun(
      ['sh', '-c', script, 'sh', transcript, String(size), String(this.ultra.offset + 1), ULTRA_MARKER, String(MAX_ATTACHMENT_LINE)],
      { timeoutMs: 30_000 },
    )
    if (exitCode === -1) {
      // A shell that could not be started is missing for good; one stopped by the time limit
      // (a slow disk, a huge first scan) is asked again from the same offset next time.
      if (/failed to start|ENOENT/.test(stderr)) this.hasNoShell = true

      return this.ultra.active
    }
    // The pipeline ends with awk, so it exits 0 whether grep matched or not; anything else is a failure.
    if (exitCode !== 0) return this.ultra.active
    this.ultra = { path: transcript, offset: size, active: ultracodeAfter(stdout, this.ultra.active) }

    return this.ultra.active
  }
}

/** How long a transcript that could not be found waits before the project folders are searched again. */
const TRANSCRIPT_RETRY_MS = 60_000

files.hooks/webhook.ts:
import type { LimitView, StatusInfo } from '../types'

/**
 * The webhook feed: the session's status sent to a URL the person sets, by
 * POST as a JSON body or by GET as query parameters, with a bearer token when
 * one is set. What is sent comes from a template file whose `{{name}}`
 * placeholders stand for the status. The template is JSON itself, so an editor checks it: a string that is
 * one placeholder alone (`"{{context}}"`) becomes that value as JSON, a number
 * staying a number and a missing value `null`; a placeholder inside a longer
 * string (`"host {{hostname}}"`) is put in as text.
 */

export type WebhookMethod = 'POST' | 'GET'

/** What the feed is set to; nothing is sent while `enabled` is false or `url` is empty. The token is kept apart, as a secret. */
export type WebhookConfig = { enabled: boolean; url: string; method: WebhookMethod }

/** The variables a template may use, in the order the dialog lists them. */
export const WEBHOOK_VARIABLES = [
  'session',
  'time',
  'timestamp',
  'hostname',
  'version',
  'cwd',
  'dir',
  'branch',
  'model',
  'modelId',
  'effort',
  'fast',
  'ultracode',
  'context',
  'cost',
  'linesAdded',
  'linesRemoved',
  'task',
  'pr',
  'prReview',
  'account',
  'fiveHour',
  'fiveHourResetsAt',
  'weekly',
  'weeklyResetsAt',
] as const

export type WebhookVariable = (typeof WEBHOOK_VARIABLES)[number]

export type WebhookValues = Record<WebhookVariable, string | number | boolean | null>

/** A template shaped like Claude Code's status line input, which a receiver written for that input already reads. */
export const DEFAULT_TEMPLATE = {
  session_id: '{{session}}',
  cwd: '{{cwd}}',
  workspace: { current_dir: '{{cwd}}' },
  model: { id: '{{modelId}}', display_name: '{{model}}' },
  version: '{{version}}',
  effort: { level: '{{effort}}' },
  fast_mode: '{{fast}}',
  context_window: { used_percentage: '{{context}}' },
  cost: { total_cost_usd: '{{cost}}', total_lines_added: '{{linesAdded}}', total_lines_removed: '{{linesRemoved}}' },
  rate_limits: {
    five_hour: { used_percentage: '{{fiveHour}}', resets_at: '{{fiveHourResetsAt}}' },
    seven_day: { used_percentage: '{{weekly}}', resets_at: '{{weeklyResetsAt}}' },
  },
  account: '{{account}}',
  hostname: '{{hostname}}',
}

/** The default template as the file holds it. */
export const DEFAULT_TEMPLATE_TEXT = `${JSON.stringify(DEFAULT_TEMPLATE, null, 2)}\n`

/** The shortest gap between two sends, and the longest the feed stays quiet while nothing changes. */
export const WEBHOOK_MIN_GAP_MS = 2000
export const WEBHOOK_HEARTBEAT_MS = 30 * 1000

export const DEFAULT_CONFIG: WebhookConfig = { enabled: false, url: '', method: 'POST' }

const PLACEHOLDER = /\{\{\s*([A-Za-z]+)\s*\}\}/g
const WHOLE = /^\{\{\s*([A-Za-z]+)\s*\}\}$/

/** The config as stored, every field checked; anything else reads as the default. */
export function parseConfig(value: unknown): WebhookConfig {
  if (typeof value !== 'object' || value === null) return DEFAULT_CONFIG
  const raw = value as Partial<WebhookConfig>

  return { enabled: raw.enabled === true, url: typeof raw.url === 'string' ? raw.url : '', method: raw.method === 'GET' ? 'GET' : 'POST' }
}

/** Why a URL cannot be posted to, or null when it can: an absolute http or https URL. */
export function urlProblem(url: string): 'empty' | 'scheme' | 'invalid' | null {
  if (url.trim() === '') return 'empty'
  if (!URL.canParse(url)) return 'invalid'
  const { protocol } = new URL(url)

  return protocol === 'http:' || protocol === 'https:' ? null : 'scheme'
}

/**
 * The template text with its placeholders filled: the body and its value, or
 * why not: the template is not JSON (`invalid`, the parser's words), or it
 * names variables there are none of (`unknown`).
 */
export function renderTemplate(
  template: string,
  values: WebhookValues,
): { body: string; value: unknown } | { unknown: string[] } | { invalid: string } {
  let parsed: unknown
  try {
    parsed = JSON.parse(template)
  } catch (error) {
    if (error instanceof SyntaxError) return { invalid: error.message }
    throw error
  }
  const known = new Set<string>(WEBHOOK_VARIABLES)
  const unknown = new Set<string>()
  const fill = (node: unknown): unknown => {
    if (typeof node === 'string') {
      const whole = WHOLE.exec(node)
      if (whole) {
        const name = whole[1] ?? ''
        if (!known.has(name)) unknown.add(name)

        return values[name as WebhookVariable] ?? null
      }

      return node.replace(PLACEHOLDER, (_, name: string) => {
        if (!known.has(name)) unknown.add(name)

        return String(values[name as WebhookVariable] ?? '')
      })
    }
    if (Array.isArray(node)) return node.map(fill)
    if (typeof node === 'object' && node !== null) return Object.fromEntries(Object.entries(node).map(([key, item]) => [key, fill(item)]))

    return node
  }
  const value = fill(parsed)
  if (unknown.size > 0) return { unknown: [...unknown] }

  return { body: JSON.stringify(value), value }
}

/** What the feed's values are built from, gathered by the hooks module. */
export type FeedInput = {
  session: string
  now: number
  hostname: string | null
  version: string | null
  cwd: string
  modelId: string
  status: StatusInfo
  cost: number | null
  account: string | null
  limits: readonly LimitView[]
}

/** The template variables' values for one moment of the session. */
export function webhookValues(input: FeedInput): WebhookValues {
  const { status } = input
  const window = (label: string) => input.limits.find(limit => limit.label === label)

  return {
    session: input.session,
    time: new Date(input.now).toISOString(),
    timestamp: input.now,
    hostname: input.hostname,
    version: input.version,
    cwd: input.cwd,
    dir: status.dir,
    branch: status.branch || null,
    model: status.model,
    modelId: input.modelId,
    effort: status.effort,
    fast: status.fast,
    ultracode: status.ultracode,
    context: status.contextUsed,
    cost: input.cost,
    linesAdded: status.linesAdded,
    linesRemoved: status.linesRemoved,
    task: status.task || null,
    pr: status.pr?.number ?? null,
    prReview: status.pr?.reviewState ?? null,
    account: input.account,
    fiveHour: window('5h')?.percent ?? null,
    fiveHourResetsAt: window('5h')?.resetsAt ?? null,
    weekly: window('wk')?.percent ?? null,
    weeklyResetsAt: window('wk')?.resetsAt ?? null,
  }
}

/** The values that say something changed: all but the clock's. */
export function changeKey(values: WebhookValues): string {
  const { time: _time, timestamp: _timestamp, ...rest } = values

  return JSON.stringify(rest)
}

/**
 * The request for one send: POST carries the filled template as a JSON body;
 * GET carries its top-level fields as query parameters (an object or array
 * as JSON text, `null` left out). A token goes in `Authorization: Bearer`.
 */
export function webhookRequest(
  config: WebhookConfig,
  rendered: { body: string; value: unknown },
  token: string | null,
): { url: string; init: { method: string; headers: Record<string, string>; body?: string } } {
  const headers: Record<string, string> = token ? { Authorization: `Bearer ${token}` } : {}
  if (config.method === 'POST') {
    return { url: config.url, init: { method: 'POST', headers: { ...headers, 'Content-Type': 'application/json' }, body: rendered.body } }
  }
  const url = new URL(config.url)
  const fields = typeof rendered.value === 'object' && rendered.value !== null && !Array.isArray(rendered.value) ? Object.entries(rendered.value) : []
  for (const [key, item] of fields) {
    if (item === null || item === undefined) continue
    url.searchParams.append(key, typeof item === 'object' ? JSON.stringify(item) : String(item))
  }

  return { url: url.toString(), init: { method: 'GET', headers } }
}

