/** The keychain item Claude Code reads its login from. */
export const LIVE_SERVICE = 'Claude Code-credentials'
/** The keychain service this mod keeps one item per saved account under. */
export const VAULT_SERVICE = 'account-switch'
/** `security`'s exit code for an item that is not there. */
export const ITEM_NOT_FOUND = 44

/** The OAuth credential document Claude Code stores, kept whole. */
export type Credential = {
  claudeAiOauth: {
    accessToken: string
    refreshToken: string
    expiresAt: number
    scopes?: string[]
    subscriptionType?: string
    rateLimitTier?: string
    [field: string]: unknown
  }
  [field: string]: unknown
}

export class KeychainError extends Error {}

function toHex(text: string): string {
  return Array.from(new TextEncoder().encode(text), byte => byte.toString(16).padStart(2, '0')).join('')
}

export function parseCredential(text: string): Credential {
  const parsed: unknown = JSON.parse(text.trim())
  const oauth = (parsed as Credential | null)?.claudeAiOauth
  if (typeof oauth?.accessToken !== 'string' || typeof oauth.refreshToken !== 'string') {
    throw new KeychainError('keychain item holds no Claude OAuth credential')
  }

  return parsed as Credential
}

/** argv printing one item's secret. */
export function findArgv(service: string, account?: string): string[] {
  return ['security', 'find-generic-password', '-s', service, ...(account ? ['-a', account] : []), '-w']
}

/** argv printing one item's attributes, its `acct` among them, without the secret. */
export function attributesArgv(service: string): string[] {
  return ['security', 'find-generic-password', '-s', service]
}

export function parseAccountName(attributes: string): string | undefined {
  return /"acct"<blob>="([^"]*)"/.exec(attributes)?.[1]
}

/**
 * The `security -i` line that creates or replaces an item. The secret travels
 * on stdin as hex, never in argv, the way Claude Code writes its own item.
 */
export function addLine(service: string, account: string, text: string): string {
  return `add-generic-password -U -a "${account}" -s "${service}" -X "${toHex(text)}"\n`
}

export function deleteArgv(service: string, account: string): string[] {
  return ['security', 'delete-generic-password', '-s', service, '-a', account]
}

files.hooks/queue.ts:
/**
 * Work run one piece at a time, in the order asked: each piece starts once
 * the one before has settled, whether it resolved or threw, and its own
 * result or error goes to its caller alone.
 *
 * A piece must not wait on another piece of the same queue: it would wait
 * for itself.
 */
export function serialQueue(): <T>(work: () => Promise<T>) => Promise<T> {
  let tail: Promise<unknown> = Promise.resolve()

  return <T>(work: () => Promise<T>): Promise<T> => {
    const run = tail.then(work, work)
    tail = run.catch(() => undefined)

    return run
  }
}

files.hooks/platform.ts:
import { removeArgv } from './shared/files'

/**
 * Where Claude Code keeps its login on this machine. macOS keeps it in the
 * keychain; Linux, WSL and Windows keep it in `<config dir>/.credentials.json`.
 */
export type Backend = 'keychain' | 'file'

export type Platform = {
  backend: Backend
  /** Windows proper (not WSL): no POSIX shell, `cmd.exe` deletes files. */
  isWindows: boolean
}

/**
 * @param osVariable the `OS` environment variable, `Windows_NT` on Windows
 * @param kernelName `uname -s` output, or undefined where `uname` did not run
 */
export function detectPlatform(osVariable: string | undefined, kernelName: string | undefined): Platform {
  if (osVariable === 'Windows_NT') return { backend: 'file', isWindows: true }
  if (kernelName === undefined) return { backend: 'file', isWindows: false }

  return { backend: kernelName.trim() === 'Darwin' ? 'keychain' : 'file', isWindows: false }
}

/** The vault file of one saved account under the file backend. */
export function vaultFilePath(claudeDirectory: string, vaultName: string, account: string): string {
  if (!/^[A-Za-z0-9_-]+$/.test(account)) throw new Error(`unsafe account id: ${account}`)

  return `${claudeDirectory}/${vaultName}/${account}.json`
}

/**
 * argv writing stdin to `path` with owner-only permissions, on a POSIX shell.
 * The umask covers a new file and folder; a file already there keeps its mode
 * through `cat >`, so it is narrowed to 600 before the secret goes in.
 */
export function privateWriteArgv(path: string): string[] {
  return ['/bin/sh', '-c', 'umask 077 && mkdir -p "$(dirname "$0")" && touch "$0" && chmod 600 "$0" && cat > "$0"', path]
}

/** argv deleting `path`, absent or not. */
export function deleteFileArgv(path: string, isWindows: boolean): string[] {
  return removeArgv([path], isWindows)
}

files.hooks/shared/locale.ts:
// Copied from shared/ by scripts/sync.mjs; edit shared/ and run the script.
export type Locale = 'en' | 'ko'

/** Short weekday names, Sunday first, as `Date#getDay` counts. */
export const WEEKDAYS: Record<Locale, readonly string[]> = {
  en: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'],
  ko: ['일', '월', '화', '수', '목', '금', '토'],
}

const KOREAN = /^(ko\b|ko[-_]|korean|한국어)/i

/**
 * Picks the display language. Claude Code's `language` setting wins when set
 * (any language without a translation here falls back to English); without
 * it the POSIX locale variables decide, in their own precedence order.
 */
export function resolveLocale(language: unknown, localeVariables: (string | undefined)[]): Locale {
  if (typeof language === 'string' && language.trim() !== '') return KOREAN.test(language.trim()) ? 'ko' : 'en'
  const locale = localeVariables.find(value => value !== undefined && value !== '')

  return locale !== undefined && KOREAN.test(locale) ? 'ko' : 'en'
}

/** The release date a changelog heading gives a version: `## 0.1.0 (2026-10-04)`. */
export function releaseDateOf(changelog: string, version: string): string | undefined {
  const escaped = version.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

  return new RegExp(`^##\\s+v?${escaped}\\s+\\((\\d{4}-\\d{2}-\\d{2})\\)`, 'm').exec(changelog)?.[1]
}

